fn pre_tool_use_payload(&self, invocation: &ToolInvocation) -> Option<PreToolUsePayload> {
    let ToolPayload::Function { arguments } = &invocation.payload else {
        return None;
    };

    parse_arguments::<ExecCommandArgs>(arguments)
        .ok()
        .map(|args| {
            let mut tool_input = serde_json::json!({ "command": args.cmd.trim().to_owned() });
            // Hooks need the structured native approval request without changing
            // the shape of legacy command-only payloads.
            if let Some(permissions) = args.sandbox_permissions {
                tool_input["sandbox_permissions"] = serde_json::json!(permissions);
            }
            if let Some(justification) = args.justification {
                tool_input["justification"] = serde_json::json!(justification);
            }
            if let Some(prefix_rule) = args.prefix_rule {
                tool_input["prefix_rule"] = serde_json::json!(prefix_rule);
            }
            PreToolUsePayload {
                tool_name: HookToolName::bash(),
                tool_input,
            }
        })
}

